fn min_max(nums: &[i32]) -> (i32, i32) {
    let mut lo = nums[0];
    let mut hi = nums[0];
    for &v in nums {
        if v < lo { lo = v; }
        if v > hi { hi = v; }
    }
    (lo, hi)
}

