use std::fs;

fn run() -> Result<usize, String> {
    let raw = fs::read_to_string("scores.txt").map_err(|e| e.to_string())?;
    let mut entries: Vec<(String, i32)> = Vec::new();
    for line in raw.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let (name, sc) = trimmed.split_once(',').ok_or_else(|| String::from("format"))?;
        let score = sc.trim().parse::<i32>().map_err(|_| String::from("num"))?;
        entries.push((String::from(name.trim()), score));
    }
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    let out = entries
        .iter()
        .map(|(n, s)| format!("{}:{}", n, s))
        .collect::<Vec<_>>()
        .join("\n") + "\n";
    fs::write("ranked.txt", out).map_err(|e| e.to_string())?;
    Ok(entries.len())
}

fn main() {
    match run() {
        Ok(n) => println!("완료: {}명", n),
        Err(e) => println!("오류: {}", e),
    }
}

