fn has_sum(nums: &[i32], target: i32) -> bool {
    if nums.len() < 2 { return false; }
    let (mut l, mut r) = (0, nums.len() - 1);
    while l < r {
        let sum = nums[l] + nums[r];
        if sum == target { return true; }
        if sum < target { l += 1; } else { r -= 1; }
    }
    false
}

