fn find_idx(nums: &[i32], target: i32) -> Option<usize> {
    let (mut l, mut r) = (0, nums.len());
    while l < r {
        let mid = l + (r - l) / 2;
        if nums[mid] == target {
            return Some(mid);
        } else if nums[mid] < target {
            l = mid + 1;
        } else {
            r = mid;
        }
    }
    None
}

fn main() {
    println!("{:?} {:?}", find_idx(&[2, 5, 8, 12], 8), find_idx(&[2, 5, 8, 12], 7));
}

