questions.solution:
fn min_coins(coins: &[i32], target: i32) -> i32 {
    if target <= 0 {
        return 0;
    }
    let t = target as usize;
    let inf = target + 1;
    let mut dp = vec![inf; t + 1];
    dp[0] = 0;
    for amt in 1..=t {
        for &c in coins {
            if c > 0 && (c as usize) <= amt {
                let prev = dp[amt - c as usize];
                if prev + 1 < dp[amt] {
                    dp[amt] = prev + 1;
                }
            }
        }
    }
    if dp[t] > target { -1 } else { dp[t] }
}

fn main() {
    println!("{}", min_coins(&[1, 3, 4], 6));
}

