use std::io::{self, Read};

fn main() {
    let mut buf = String::new();
    io::stdin().read_to_string(&mut buf).unwrap();
    let mut val = 0;
    let mut errors = 0;
    for raw in buf.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        let parsed = match line.split_once(' ') {
            Some((op, arg)) => match (op, arg.trim().parse::<i32>()) {
                ("ADD", Ok(n)) => { val += n; true }
                ("SUB", Ok(n)) => { val -= n; true }
                _ => false,
            },
            None => false,
        };
        if !parsed {
            errors += 1;
        }
    }
    println!("val={} errors={}", val, errors);
}

