fn max_window(nums: &[i32], k: usize) -> i32 {
    let mut win: i32 = nums[..k].iter().sum();
    let mut best = win;
    for i in k..nums.len() {
        win += nums[i] - nums[i - k];
        best = best.max(win);
    }
    best
}

fn main() {
    println!("{}", max_window(&[2, 1, 5, 1, 3, 2], 3));
}

fn kadane(nums: &[i32]) -> i32 {
    let mut cur = nums[0];
    let mut best = nums[0];
    for &x in &nums[1..] {
        cur = x.max(cur + x);
        best = best.max(cur);
    }
    best
}

fn main() {
    println!("{} {}", kadane(&[-2, 1, -3, 4, -1, 2, 1]), kadane(&[-5, -2, -8]));
}

