use std::collections::VecDeque;

fn order_of(prio: &[i32], target: usize) -> usize {
    let mut q: VecDeque<(usize, i32)> = prio.iter().copied().enumerate().collect();
    let mut printed = 0;
    while let Some(cur) = q.pop_front() {
        if q.iter().any(|&x| x.1 > cur.1) {
            q.push_back(cur);
        } else {
            printed += 1;
            if cur.0 == target { return printed; }
        }
    }
    printed
}

fn main() {
    println!("{}", order_of(&[2, 1, 3, 2], 2));
}

