import heapq

def min_rooms(meetings):
    if not meetings:
        return 0
    ends = []
    for start, end in sorted(meetings, key=lambda x: (x[0], x[1])):
        if ends and ends[0] <= start:
            heapq.heappop(ends)
        heapq.heappush(ends, end)
    return len(ends)

