fn eval_rpn(tokens: &[&str]) -> i32 {
    let mut st: Vec<i32> = Vec::new();
    for &t in tokens {
        match t {
            "+" => { let b = st.pop().unwrap(); let a = st.pop().unwrap(); st.push(a + b); }
            "*" => { let b = st.pop().unwrap(); let a = st.pop().unwrap(); st.push(a * b); }
            _ => st.push(t.parse().unwrap()),
        }
    }
    st[0]
}

