struct UpTo { cur: i32, end: i32 }
impl Iterator for UpTo {
    type Item = i32;
    fn next(&mut self) -> Option<Self::Item> {
        if self.cur > self.end { return None; }
        let v = self.cur;
        self.cur += 1;
        Some(v)
    }
}

fn main() {
    let it_sum: i32 = UpTo { cur: 1, end: 4 }.sum();
    println!("{} {}", it_sum, sum_args!(2, 4, 6));
}

