fn rle(s: &str) -> String {
    let mut it = s.chars();
    let mut prev = match it.next() {
        Some(c) => c,
        None => return String::new(),
    };
    let mut cnt = 1;
    let mut out = String::new();
    for ch in it {
        if ch == prev {
            cnt += 1;
        } else {
            out.push_str(&format!("{}{}", prev, cnt));
            prev = ch;
            cnt = 1;
        }
    }
    out.push_str(&format!("{}{}", prev, cnt));
    out
}

fn main() {
    println!("{}", rle("aaabbc"));
}

