fn build_report(csv: &str) -> (String, i32) {
    let mut map: BTreeMap<&str, i32> = BTreeMap::new();
    let mut grand = 0;
    for line in csv.lines().skip(1) {
        let c: Vec<&str> = line.split(',').collect();
        if c.len() == 3 {
            let amt = c[1].trim().parse::<i32>().unwrap_or(0) * c[2].trim().parse::<i32>().unwrap_or(0);
            *map.entry(c[0].trim()).or_insert(0) += amt;
            grand += amt;
        }
    }
    let body: Vec<String> = map.into_iter().map(|(k, v)| format!("{}:{}", k, v)).collect();
    (body.join("\n"), grand)
}

