use std::collections::BTreeMap;
use std::fs;

fn main() {
    let users_raw = fs::read_to_string("users.csv").expect("users.csv 읽기 실패");
    let scores_raw = fs::read_to_string("scores.csv").expect("scores.csv 읽기 실패");
    let mut users: BTreeMap<&str, &str> = BTreeMap::new();
    for line in users_raw.lines().skip(1) {
        let c: Vec<&str> = line.split(',').collect();
        if c.len() == 2 {
            users.insert(c[0].trim(), c[1].trim());
        }
    }
    let mut stats: BTreeMap<&str, (i32, i32)> = BTreeMap::new();
    for line in scores_raw.lines().skip(1) {
        let c: Vec<&str> = line.split(',').collect();
        if c.len() == 2 {
            let id = c[0].trim();
            if users.contains_key(id) {
                if let Ok(score) = c[1].trim().parse::<i32>() {
                    let e = stats.entry(id).or_insert((0, 0));
                    e.0 += score;
                    e.1 += 1;
                }
            }
        }
    }
    let mut lines: Vec<String> = Vec::new();
    let mut passed = 0;
    for (id, name) in &users {
        let (sum, cnt) = stats.get(id).copied().unwrap_or((0, 0));
        let avg = if cnt > 0 { sum / cnt } else { 0 };
        let grade = if avg >= 70 {
            passed += 1;
            "PASS"
        } else {
            "FAIL"
        };
        lines.push(format!("{},{},{},{}", id, name, avg, grade));
    }
    fs::write("grades.txt", lines.join("\n")).expect("grades.txt 쓰기 실패");
    println!("passed={}", passed);
}

