fn has_pair_sum(nums: &[i32], target: i32) -> bool {
    if nums.len() < 2 {
        return false;
    }
    let (mut l, mut r) = (0, nums.len() - 1);
    while l < r {
        let sum = nums[l] + nums[r];
        if sum == target {
            return true;
        } else if sum < target {
            l += 1;
        } else {
            r -= 1;
        }
    }
    false
}

fn main() {
    println!("{}", has_pair_sum(&[1, 2, 4, 7, 11], 9));
    println!("{}", has_pair_sum(&[1, 2, 4, 7, 11], 10));
}

