use std::collections::VecDeque;

fn main() {
    let raw = [
        "S...#",
        ".##.#",
        "....#",
        "#.###",
        "#...E",
    ];
    let g: Vec<Vec<char>> = raw.iter().map(|s| s.chars().collect()).collect();
    let (h, w) = (g.len(), g[0].len());
    let (mut sr, mut sc, mut er, mut ec) = (0, 0, 0, 0);
    for r in 0..h {
        for c in 0..w {
            if g[r][c] == 'S' { sr = r; sc = c; }
            if g[r][c] == 'E' { er = r; ec = c; }
        }
    }
    let mut dist = vec![vec![-1_i32; w]; h];
    let mut q = VecDeque::from([(sr, sc)]);
    dist[sr][sc] = 0;
    let dirs = [(-1isize, 0), (1, 0), (0, -1), (0, 1)];
    while let Some((r, c)) = q.pop_front() {
        for (dr, dc) in dirs {
            if let (Some(nr), Some(nc)) = (r.checked_add_signed(dr), c.checked_add_signed(dc)) {
                if nr < h && nc < w && g[nr][nc] != '#' && dist[nr][nc] == -1 {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.push_back((nr, nc));
                }
            }
        }
    }
    println!("{}", dist[er][ec]);
}

