questions.solution:
fn can_ship(weights: &[i32], days: i32, cap: i32) -> bool {
    let (mut used, mut cur) = (1, 0);
    for &w in weights {
        if cur + w > cap {
            used += 1;
            cur = 0;
        }
        cur += w;
    }
    used <= days
}

fn min_capacity(weights: &[i32], days: i32) -> i32 {
    if weights.is_empty() {
        return 0;
    }
    let mut lo = *weights.iter().max().unwrap();
    let mut hi: i32 = weights.iter().sum();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if can_ship(weights, days, mid) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    lo
}

fn main() {
    println!("{}", min_capacity(&[3, 2, 2, 4, 1, 4], 3));
}

